import { gsap } from 'gsap';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, mix, uv, vec2, vec3, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ============================================================================
  // CARD GEOMETRY & MATERIAL SETUP
  // ============================================================================

  const cardWidth = 1.5;
  const cardHeight = 1.9;
  const gap = 0.25;
  const totalWidth = cardWidth * 3 + gap * 2;
  const startX = -totalWidth / 2;

  const cornerRadius = 0.06;
  const borderWidth = 0.006;
  const padding = 0.375;

  // Create rounded-rect card geometry
  const createCardGeometry = () => {
    const geometry = new THREE.PlaneGeometry(cardWidth, cardHeight, 32, 32);
    const positions = geometry.attributes.position;

    // Round corners by modifying vertices
    for (let i = 0; i < positions.count; i++) {
      const x = positions.getX(i);
      const y = positions.getY(i);

      const hw = cardWidth / 2;
      const hh = cardHeight / 2;

      // Distance from corner
      const cornerX = Math.abs(x) - (hw - cornerRadius);
      const cornerY = Math.abs(y) - (hh - cornerRadius);

      if (cornerX > 0 && cornerY > 0) {
        const dist = Math.sqrt(cornerX * cornerX + cornerY * cornerY);
        if (dist > cornerRadius) {
          const scale = cornerRadius / dist;
          const newX = x > 0 ? hw - cornerRadius + cornerX * scale : -(hw - cornerRadius + cornerX * scale);
          const newY = y > 0 ? hh - cornerRadius + cornerY * scale : -(hh - cornerRadius + cornerY * scale);
          positions.setXY(i, newX, newY);
        }
      }
    }
    positions.needsUpdate = true;
    return geometry;
  };

  // Card material with vertical gradient ramp
  const cardMaterial = new MeshStandardNodeMaterial({
    colorNode: mix(
      color('#191921'),
      color('#121218'),
      uv().y
    ),
    roughnessValue: 0.6,
    metalnessValue: 0.25,
    clearcoatValue: 0.15,
    side: THREE.FrontSide
  });

  // Disc material (icon seat)
  const discMaterial = new MeshStandardNodeMaterial({
    colorNode: color('#16161d'),
    roughnessValue: 0.55,
    metalnessValue: 0.5,
    clearcoatValue: 0.2,
    side: THREE.FrontSide
  });

  // ============================================================================
  // TEXT & ICON SETUP
  // ============================================================================

  const cardData = [
    {
      icon: '01',
      title: 'In-House Calibre',
      body: 'Every movement is designed, machined, and finished under one roof.'
    },
    {
      icon: '02',
      title: 'Five-Year Guarantee',
      body: 'Each piece is serviced free of charge for five years from delivery.'
    },
    {
      icon: '03',
      title: 'Hand-Finished Dials',
      body: 'Guilloche cut on a 1912 rose engine, one dial at a time.'
    }
  ];

  const cards = [];
  const timelines = [];

  for (let i = 0; i < 3; i++) {
    const cardGroup = new THREE.Group();
    cardGroup.position.x = startX + i * (cardWidth + gap) + cardWidth / 2;
    cardGroup.position.z = 0;

    // Card plane
    const cardGeo = createCardGeometry();
    const cardMesh = new THREE.Mesh(cardGeo, cardMaterial);
    cardMesh.position.z = 0;
    cardGroup.add(cardMesh);

    // Border indicator (thin plane slightly in front)
    const borderMat = new MeshBasicNodeMaterial({
      colorNode: color('#26262f'),
      side: THREE.FrontSide
    });
    const borderGeo = new THREE.PlaneGeometry(cardWidth, cardHeight, 2, 2);
    const borderMesh = new THREE.Mesh(borderGeo, borderMat);
    borderMesh.position.z = 0.001;
    borderMesh.scale.set(
      (cardWidth - borderWidth) / cardWidth,
      (cardHeight - borderWidth) / cardHeight,
      1
    );
    cardGroup.add(borderMesh);

    // Icon seat disc (extruded)
    const discGeo = new THREE.CylinderGeometry(0.2, 0.2, 0.05, 32);
    const discMesh = new THREE.Mesh(discGeo, discMaterial);
    discMesh.position.z = 0.05;
    discMesh.rotation.x = Math.PI / 2;
    cardGroup.add(discMesh);

    // Icon glyph text (emissive)
    const iconText = ctx.fontAtlas.createText(cardData[i].icon, {
      fontSize: 20,
      color: '#ff2a38',
      align: 'center'
    });
    iconText.position.z = 0.08;
    iconText.position.y = cardHeight / 2 - padding - 0.1;
    cardGroup.add(iconText);

    // Title text
    const titleText = ctx.fontAtlas.createText(cardData[i].title, {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'left'
    });
    titleText.position.z = 0.05;
    titleText.position.x = -cardWidth / 2 + padding;
    titleText.position.y = cardHeight / 2 - padding - 0.35;
    cardGroup.add(titleText);

    // Body text
    const bodyText = ctx.fontAtlas.createText(cardData[i].body, {
      fontSize: 13,
      color: '#b0b0c0',
      align: 'left',
      maxWidthPx: (cardWidth - padding * 2) * 100
    });
    bodyText.position.z = 0.05;
    bodyText.position.x = -cardWidth / 2 + padding;
    bodyText.position.y = cardHeight / 2 - padding - 0.65;
    cardGroup.add(bodyText);

    // Stagger animation: fade-up
    cardGroup.position.y = 0.2;
    cardGroup.position.z = 0;
    cardGroup.material = cardMaterial;

    const timeline = gsap.timeline({ paused: true });
    timeline.to(cardGroup.position, {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      delay: i * 0.08
    }, 0);

    timeline.from(cardGroup, {
      opacity: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)',
      delay: i * 0.08
    }, 0);

    timeline.play();
    timelines.push(timeline);

    // Hover interaction
    cardGroup.userData.handlers = cardGroup.userData.handlers || {};

    let hovering = false;
    const hoverTimeline = gsap.timeline({ paused: true });
    hoverTimeline.to(cardGroup.position, {
      y: 0.06,
      z: 0.12,
      duration: 0.18,
      ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    }, 0);

    // Icon emissive brighten on hover
    const iconGlyphChild = cardGroup.children.find(c => c.isGroup);
    if (iconText) {
      hoverTimeline.to(iconText, {
        emissiveIntensity: 2.2,
        duration: 0.18,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      }, 0);
    }

    cardGroup.userData.handlers.hover = (evt) => {
      if (evt.type === 'enter' && !hovering) {
        hovering = true;
        hoverTimeline.play();
      } else if (evt.type === 'leave' && hovering) {
        hovering = false;
        hoverTimeline.reverse();
      }
    };

    group.add(cardGroup);
    cards.push(cardGroup);
  }

  // ============================================================================
  // BACKDROP STAGE
  // ============================================================================

  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: mix(
      color('#191921'),
      color('#121218'),
      uv().y.mul(0.5).add(0.5)
    ),
    side: THREE.FrontSide
  });
  const backdropMesh = new THREE.Mesh(backdropGeo, backdropMat);
  backdropMesh.position.z = -2.5;
  group.add(backdropMesh);

  // ============================================================================
  // CONTACT SHADOW PLANES (under cards)
  // ============================================================================

  const shadowMaterial = new MeshBasicNodeMaterial({
    colorNode: color('#000000'),
    transparent: true,
    opacity: 0.5,
    side: THREE.FrontSide
  });

  for (let i = 0; i < 3; i++) {
    const shadowGeo = new THREE.PlaneGeometry(1.8, 0.3);
    const shadowMesh = new THREE.Mesh(shadowGeo, shadowMaterial);
    shadowMesh.position.x = startX + i * (cardWidth + gap) + cardWidth / 2;
    shadowMesh.position.y = -cardHeight / 2 - 0.1;
    shadowMesh.position.z = -0.05;
    group.add(shadowMesh);
  }

  // ============================================================================
  // LIGHTS
  // ============================================================================

  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 3, 1);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, 1, -1);
  group.add(rimLight);

  // ============================================================================
  // CLEANUP & RETURN
  // ============================================================================

  group.userData.cleanup = () => {
    timelines.forEach(tl => tl.kill());
    cards.forEach(card => {
      card.traverse(obj => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      });
    });
    backdropMesh.geometry.dispose();
    backdropMesh.material.dispose();
    cardMaterial.dispose();
    discMaterial.dispose();
    borderMat.dispose();
    shadowMaterial.dispose();
  };

  return group;
}
